mapper.select:
SELECT t.table_id as id, t.table_schema as tableSchema, t.table_name as `name`, t.table_desc as tableDesc, t.is_fact_table as isFactTable, t.support_query_engines as supportQueryEngines, t.granularity, t.orig_table_name as origTableName, t.is_active as isActive, DATE_FORMAT( t.created_time, '%Y-%m-%d %H:%i:%s' ) AS createdTime, DATE_FORMAT( t.updated_time, '%Y-%m-%d %H:%i:%s' ) AS updatedTime, t.created_by as createdBy, t.updated_by as updatedBy, t.table_owner as tableOwner, t.is_kpi_table as isKpiTable FROM ssd_table_def t where 1=1
ORDER BY ${sortKey} ${sortType}
ORDER BY t.created_time desc
LIMIT ${pageRowLower}, ${prePageSize}

